/*!
 * 极简 QR Code 生成器（byte 模式，纠错级别 M，版本自动选择）
 * 用于 LY云计算 收银台渲染支付宝支付二维码，完全离线，无外部依赖。
 * 算法参考 QR Code 标准 ISO/IEC 18004。
 */
(function (global) {
    'use strict';

    // ---------- GF(256) 运算表 ----------
    var EXP = new Array(256), LOG = new Array(256);
    (function () {
        var x = 1;
        for (var i = 0; i < 255; i++) {
            EXP[i] = x;
            LOG[x] = i;
            x <<= 1;
            if (x & 0x100) x ^= 0x11d;
        }
        EXP[255] = EXP[0];
    })();

    function gmul(a, b) {
        if (a === 0 || b === 0) return 0;
        return EXP[(LOG[a] + LOG[b]) % 255];
    }

    // ---------- RS 纠错码生成 ----------
    function rsGenerator(degree) {
        var poly = [1];
        for (var i = 0; i < degree; i++) {
            var next = new Array(poly.length + 1);
            for (var j = 0; j < next.length; j++) next[j] = 0;
            for (var k = 0; k < poly.length; k++) {
                next[k] ^= poly[k];
                next[k + 1] ^= gmul(poly[k], EXP[i]) === 0 && poly[k] === 0 ? 0 : gmul(poly[k], EXP[i]);
            }
            poly = next;
        }
        return poly;
    }

    function rsEncode(data, ecLen) {
        var gen = rsGenerator(ecLen);
        var res = data.slice();
        for (var i = 0; i < ecLen; i++) res.push(0);
        for (var i = 0; i < data.length; i++) {
            var coef = res[i];
            if (coef === 0) continue;
            for (var j = 1; j < gen.length; j++) {
                res[i + j] ^= gmul(gen[j], coef);
            }
        }
        return res.slice(data.length);
    }

    // ---------- 版本信息（仅覆盖常用版本 1-10，纠错 M） ----------
    // [每块数据码字数, 每块纠错码字数, 块数]
    var VERSION_M = {
        1:  [16, 10, 1],
        2:  [28, 16, 1],
        3:  [44, 26, 1],
        4:  [64, 18, 2],
        5:  [86, 24, 2],
        6:  [108, 16, 4],
        7:  [124, 18, 4],
        8:  [154, 22, 4],
        9:  [182, 22, 5],
        10: [216, 26, 5]
    };

    function byteCapacity(version) {
        var v = VERSION_M[version];
        if (!v) return 0;
        var totalData = v[0] * v[2];
        var headerBits = 4 + (version < 10 ? 8 : 16);
        return Math.floor((totalData * 8 - headerBits) / 8);
    }

    // ---------- 位流 ----------
    function BitBuffer() { this.buf = []; this.len = 0; }
    BitBuffer.prototype.put = function (value, bits) {
        for (var i = bits - 1; i >= 0; i--) {
            this.putBit(((value >>> i) & 1) === 1);
        }
    };
    BitBuffer.prototype.putBit = function (bit) {
        var idx = this.len >> 3;
        if (this.buf.length <= idx) this.buf.push(0);
        if (bit) this.buf[idx] |= 0x80 >>> (this.len & 7);
        this.len++;
    };

    // ---------- UTF-8 编码 ----------
    function toUtf8(str) {
        var out = [], i, c;
        for (i = 0; i < str.length; i++) {
            c = str.charCodeAt(i);
            if (c < 0x80) out.push(c);
            else if (c < 0x800) {
                out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
            } else if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
                var c2 = str.charCodeAt(i + 1);
                var cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
                out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f),
                         0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
                i++;
            } else {
                out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
            }
        }
        return out;
    }

    // ---------- 对齐图案位置 ----------
    var ALIGN = {
        1: [], 2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30],
        6: [6, 34], 7: [6, 22, 38], 8: [6, 24, 42], 9: [6, 26, 46], 10: [6, 28, 50]
    };

    // ---------- 主编码函数 ----------
    function encode(text) {
        var bytes = toUtf8(text);

        // 选择最小可用版本
        var version = 0;
        for (var v = 1; v <= 10; v++) {
            if (bytes.length <= byteCapacity(v)) { version = v; break; }
        }
        if (!version) throw new Error('内容过长，无法生成二维码');

        var cfg = VERSION_M[version];
        var size = version * 4 + 17;

        // ---- 构造位流 ----
        var bb = new BitBuffer();
        bb.put(4, 4);                                   // byte 模式
        bb.put(bytes.length, version < 10 ? 8 : 16);    // 字符数
        for (var i = 0; i < bytes.length; i++) bb.put(bytes[i], 8);

        var totalDataBits = cfg[0] * cfg[2] * 8;

        // 终止符
        var remain = totalDataBits - bb.len;
        bb.put(0, Math.min(4, remain));

        // 补齐到字节边界
        while (bb.len % 8 !== 0) bb.putBit(false);

        // 填充字节 0xEC / 0x11
        var pad = [0xEC, 0x11], pi = 0;
        while (bb.len < totalDataBits) {
            bb.put(pad[pi % 2], 8);
            pi++;
        }

        var dataBytes = bb.buf.slice(0, totalDataBits / 8);

        // ---- 分块 + 纠错 ----
        var blockCount = cfg[2];
        var dataPerBlock = cfg[0];
        var ecPerBlock = cfg[1];
        var dataBlocks = [], ecBlocks = [];

        for (var b = 0; b < blockCount; b++) {
            var blk = dataBytes.slice(b * dataPerBlock, (b + 1) * dataPerBlock);
            dataBlocks.push(blk);
            ecBlocks.push(rsEncode(blk, ecPerBlock));
        }

        // ---- 交织 ----
        var finalBytes = [];
        var maxData = dataPerBlock;
        for (var c = 0; c < maxData; c++) {
            for (var b2 = 0; b2 < blockCount; b2++) {
                if (c < dataBlocks[b2].length) finalBytes.push(dataBlocks[b2][c]);
            }
        }
        for (var c2 = 0; c2 < ecPerBlock; c2++) {
            for (var b3 = 0; b3 < blockCount; b3++) {
                finalBytes.push(ecBlocks[b3][c2]);
            }
        }

        // 转为位流
        var bits = [];
        for (var k = 0; k < finalBytes.length; k++) {
            for (var j = 7; j >= 0; j--) bits.push((finalBytes[k] >> j) & 1);
        }

        // ---- 构建矩阵 ----
        var m = [], reserved = [];
        for (var y = 0; y < size; y++) {
            m.push(new Array(size).fill(0));
            reserved.push(new Array(size).fill(false));
        }

        function setF(x, y, val) {
            if (x < 0 || y < 0 || x >= size || y >= size) return;
            m[y][x] = val;
            reserved[y][x] = true;
        }

        // 定位图案
        function finder(cx, cy) {
            for (var dy = -4; dy <= 4; dy++) {
                for (var dx = -4; dx <= 4; dx++) {
                    var x = cx + dx, y = cy + dy;
                    if (x < 0 || y < 0 || x >= size || y >= size) continue;
                    var dist = Math.max(Math.abs(dx), Math.abs(dy));
                    setF(x, y, (dist === 2 || dist === 4) ? 0 : 1);
                }
            }
            // 内部保留区也标记为已占用
            for (var dy2 = -4; dy2 <= 4; dy2++) {
                for (var dx2 = -4; dx2 <= 4; dx2++) {
                    var x2 = cx + dx2, y2 = cy + dy2;
                    if (x2 < 0 || y2 < 0 || x2 >= size || y2 >= size) continue;
                    reserved[y2][x2] = true;
                }
            }
        }
        finder(3, 3);
        finder(size - 4, 3);
        finder(3, size - 4);

        // 定位图案内的实心部分修正
        function finderCore(cx, cy) {
            for (var dy = -1; dy <= 1; dy++) {
                for (var dx = -1; dx <= 1; dx++) {
                    setF(cx + dx, cy + dy, 1);
                }
            }
        }
        finderCore(3, 3);
        finderCore(size - 4, 3);
        finderCore(3, size - 4);

        // 定时图案
        for (var i2 = 8; i2 < size - 8; i2++) {
            var val = (i2 % 2 === 0) ? 1 : 0;
            setF(i2, 6, val);
            setF(6, i2, val);
        }

        // 校正图案
        var aligns = ALIGN[version] || [];
        for (var a1 = 0; a1 < aligns.length; a1++) {
            for (var a2 = 0; a2 < aligns.length; a2++) {
                var ax = aligns[a1], ay = aligns[a2];
                // 跳过与定位图案重叠的位置
                if ((ax === 6 && ay === 6) ||
                    (ax === 6 && ay === size - 7) ||
                    (ax === size - 7 && ay === 6)) continue;
                for (var dy3 = -2; dy3 <= 2; dy3++) {
                    for (var dx3 = -2; dx3 <= 2; dx3++) {
                        var dist3 = Math.max(Math.abs(dx3), Math.abs(dy3));
                        setF(ax + dx3, ay + dy3, dist3 === 1 ? 0 : 1);
                    }
                }
            }
        }

        // 格式信息（纠错级别 M = 00，掩码稍后填入，先预留）
        // 版本信息（版本 >= 7）
        if (version >= 7) {
            var vInfo = versionInfoBits(version);
            for (var i4 = 0; i4 < 18; i4++) {
                var bit = (vInfo >> i4) & 1;
                var xx = Math.floor(i4 / 3);
                var yy = i4 % 3;
                setF(size - 11 + yy, xx, bit);
                setF(xx, size - 11 + yy, bit);
            }
        }

        // 预留格式信息区
        for (var i5 = 0; i5 <= 8; i5++) {
            reserved[8][i5] = true;
            reserved[i5][8] = true;
        }
        for (var i6 = 0; i6 < 8; i6++) {
            reserved[8][size - 1 - i6] = true;
            reserved[size - 1 - i6][8] = true;
        }
        reserved[size - 8][8] = true;

        // ---- 数据摆放 ----
        var bitIdx = 0, upward = true;
        for (var col = size - 1; col > 0; col -= 2) {
            if (col === 6) col--; // 跳过定时图案列
            for (var n = 0; n < size; n++) {
                var row = upward ? (size - 1 - n) : n;
                for (var c3 = 0; c3 < 2; c3++) {
                    var x3 = col - c3;
                    if (reserved[row][x3]) continue;
                    var bitVal = bitIdx < bits.length ? bits[bitIdx] : 0;
                    m[row][x3] = bitVal;
                    bitIdx++;
                }
            }
            upward = !upward;
        }

        // ---- 掩码选择（对 8 种掩码评分，取最低分） ----
        var bestMask = 0, bestScore = Infinity, bestMatrix = null;

        for (var mask = 0; mask < 8; mask++) {
            var mm = maskMatrix(m, reserved, size, mask);
            writeFormat(mm, size, mask);
            var score = evaluate(mm, size);
            if (score < bestScore) {
                bestScore = score;
                bestMask = mask;
                bestMatrix = mm;
            }
        }

        return { matrix: bestMatrix, size: size, version: version };
    }

    // ---------- 掩码处理 ----------
    function maskFn(mask, x, y) {
        switch (mask) {
            case 0: return (x + y) % 2 === 0;
            case 1: return y % 2 === 0;
            case 2: return x % 3 === 0;
            case 3: return (x + y) % 3 === 0;
            case 4: return (Math.floor(y / 2) + Math.floor(x / 3)) % 2 === 0;
            case 5: return ((x * y) % 2) + ((x * y) % 3) === 0;
            case 6: return (((x * y) % 2) + ((x * y) % 3)) % 2 === 0;
            case 7: return (((x + y) % 2) + ((x * y) % 3)) % 2 === 0;
        }
        return false;
    }

    function maskMatrix(src, reserved, size, mask) {
        var out = [];
        for (var y = 0; y < size; y++) {
            out.push(new Array(size));
            for (var x = 0; x < size; x++) {
                if (reserved[y][x]) {
                    out[y][x] = src[y][x];
                } else {
                    out[y][x] = maskFn(mask, x, y) ? (src[y][x] ^ 1) : src[y][x];
                }
            }
        }
        return out;
    }

    // 格式信息 BCH(15,5)
    function formatBits(ecLevel, mask) {
        var data = (ecLevel << 3) | mask; // ecLevel M = 0
        var bits = data << 10;
        var g = 0x537; // 0b10100110111
        for (var i = 14; i >= 10; i--) {
            if ((bits >> i) & 1) {
                bits ^= g << (i - 10);
            }
        }
        return ((data << 10) | bits) ^ 0x5412;
    }

    function writeFormat(m, size, mask) {
        var fmt = formatBits(0, mask); // M 级纠错 = 0b00
        for (var i = 0; i < 15; i++) {
            var bit = (fmt >> i) & 1;
            // 左上
            if (i < 6) m[8][i] = bit;
            else if (i === 6) m[8][7] = bit;
            else if (i === 7) m[8][8] = bit;
            else if (i === 8) m[7][8] = bit;
            else m[14 - i][8] = bit;

            // 右上 / 左下
            if (i < 8) m[8][size - 1 - i] = bit;
            else m[size - 15 + i][8] = bit;
        }
        m[size - 8][8] = 1; // 固定暗模块
    }

    // 版本信息 BCH(18,6)
    function versionInfoBits(version) {
        var bits = version << 12;
        var g = 0x1f25;
        for (var i = 17; i >= 12; i--) {
            if ((bits >> i) & 1) {
                bits ^= g << (i - 12);
            }
        }
        return (version << 12) | bits;
    }

    // ---------- 评分（简化版，用于选择掩码） ----------
    function evaluate(m, size) {
        var score = 0, x, y;
        // 规则1：同色连续块
        for (y = 0; y < size; y++) {
            var run = 1;
            for (x = 1; x < size; x++) {
                if (m[y][x] === m[y][x - 1]) run++;
                else { if (run >= 5) score += 3 + (run - 5); run = 1; }
            }
            if (run >= 5) score += 3 + (run - 5);
        }
        for (x = 0; x < size; x++) {
            var run2 = 1;
            for (y = 1; y < size; y++) {
                if (m[y][x] === m[y - 1][x]) run2++;
                else { if (run2 >= 5) score += 3 + (run2 - 5); run2 = 1; }
            }
            if (run2 >= 5) score += 3 + (run2 - 5);
        }
        // 规则2：2x2 同色块
        for (y = 0; y < size - 1; y++) {
            for (x = 0; x < size - 1; x++) {
                var v = m[y][x];
                if (v === m[y][x + 1] && v === m[y + 1][x] && v === m[y + 1][x + 1]) score += 3;
            }
        }
        // 规则4：暗模块比例
        var dark = 0;
        for (y = 0; y < size; y++) for (x = 0; x < size; x++) if (m[y][x]) dark++;
        var ratio = dark / (size * size) * 100;
        score += Math.floor(Math.abs(ratio - 50) / 5) * 10;
        return score;
    }

    // ---------- 渲染 ----------
    function render(canvas, text, options) {
        options = options || {};
        var quiet = options.quiet != null ? options.quiet : 4;
        var fg = options.color || '#000000';
        var bg = options.background || '#ffffff';

        var result = encode(text);
        var m = result.matrix, size = result.size;
        var total = size + quiet * 2;
        var scale = Math.max(1, Math.floor((options.size || 220) / total));

        canvas.width = total * scale;
        canvas.height = total * scale;
        canvas.style.width = (options.size || 220) + 'px';
        canvas.style.height = (options.size || 220) + 'px';

        var ctx = canvas.getContext('2d');
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = fg;

        for (var y = 0; y < size; y++) {
            for (var x = 0; x < size; x++) {
                if (m[y][x]) {
                    ctx.fillRect((x + quiet) * scale, (y + quiet) * scale, scale, scale);
                }
            }
        }
        return result;
    }

    global.QRCodeLib = { render: render, encode: encode };
})(window);
